def _check_with_store(
    self,
    batch: BoundPedersenOpeningBatch,
    root: bytes,
    binding: ReplayBinding,
    session_id: bytes,
    current: int,
) -> bool:
    """The store-backed claim/verify/consume flow for :meth:`check`.

    The claim is taken in one short transaction (or an expired claim is
    taken over and issued a fresh random token); verification runs with
    no transaction held; only the token returned by the winning claim
    can consume the id, and every rejection or escaped error restores
    the id to pending with that same token. A stale token (a claim
    taken over while verification ran) neither consumes nor restores
    anything.
    """
    token = self._store.claim(session_id, binding)
    if token is None:
        return False  # unknown id, already consumed, live claim, or unequal binding
    committed = False
    try:
        if not hmac.compare_digest(
            binding.digest,
            _bound_pedersen_opening_replay_digest(
                batch, root, session_id, binding.expires_at
            ),
        ):
            return False  # the presented batch/root is not the one originally bound
        if binding.expires_at is not None and current >= binding.expires_at:
            return False  # expired: rejection does not consume the id
        if not verify_pedersen_opening_batch_bound(batch, root):
            return False
        if not self._store.commit(session_id, token):
            return False  # the lease expired and another check took over
        committed = True
        return True
    finally:
        # A False result, an expiry or an escaped error hands the id back
        # to pending, but only while the current token still owns it;
        # after commit() (or a takeover) the token is stale and this is a
        # no-op, leaving the id consumed or re-claimed by the new owner.
        if not committed:
            self._store.release(session_id, token)

class RegionBatchReplayGuardTest(unittest.TestCase):
    """Single-use replay bindings for region-proof batches."""

    DOMAIN = b"zr/rgbr/v1"
    PRIME_A = SMALL_PRIME
    PRIME_B = 104723

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self._tmp.name, "rgbr.db")
        self.entries = self.make_entries()

    def tearDown(self):
        self._tmp.cleanup()

    def make_entry(
        self, x, y, *, prime, x_blinding, y_blinding,
        region=None, context=b"batch",
    ):
        region = Region(0, 10, 20, 30) if region is None else region
        x_commitment, x_r = pedersen_commit(
            x, region.min_x, region.max_x,
            prime=prime, generator=3, blinding=x_blinding,
        )
        y_commitment, y_r = pedersen_commit(
            y, region.min_y, region.max_y,
            prime=prime, generator=3, blinding=y_blinding,
        )
        proof = prove_region(
            x_commitment, y_commitment, x, y, x_r, y_r, region,
            context=context, randbelow=counter_randbelow(),
        )
        return RegionBatchEntry(x_commitment, y_commitment, region, proof, context)

    def make_entries(self):
        return [
            self.make_entry(4, 22, prime=self.PRIME_A, x_blinding=1001, y_blinding=1002),
            self.make_entry(7, 28, prime=self.PRIME_A, x_blinding=2001, y_blinding=2002),
            self.make_entry(3, 25, prime=self.PRIME_B, x_blinding=3001, y_blinding=3002),
        ]

    def make_store(self, *args, **kwargs):
        return SQLiteReplayStore(self.path, *args, **kwargs)

    def raw_rows(self):
        conn = sqlite3.connect(self.path)
        try:
            return conn.execute(
                "SELECT namespace, domain, session_id, state FROM replay_sessions_v1"
            ).fetchall()
        finally:
            conn.close()

    @staticmethod
    def bound_region_leaf(entry):
        items = [b"zkregion/region-bound/v1"]
        for c in (entry.x_commitment, entry.y_commitment):
            items += [str(v).encode("ascii")
                      for v in (c.element, c.lower, c.upper, c.prime, c.generator, c.h)]
        r = entry.region
        items += [str(v).encode("ascii")
                  for v in (r.min_x, r.max_x, r.min_y, r.max_y)]
        items.append(entry.context)
        for sub in (entry.proof.x_proof, entry.proof.y_proof):
            for seq in (sub.t, sub.e, sub.s):
                items.append(str(len(seq)).encode("ascii"))
                items += [str(v).encode("ascii") for v in seq]
        return b"".join(len(item).to_bytes(4, "big") + item for item in items)

    def expected_digest(self, entries, session_id, expires_at=None):
        def F(item):
            return len(item).to_bytes(4, "big") + item

        def U(value):
            return value.to_bytes(8, "big")

        def S(sequence, transform):
            return F(U(len(sequence))) + b"".join(
                F(transform(item)) for item in sequence
            )

        expiry = b"\x00" if expires_at is None else b"\x01" + expires_at.to_bytes(8, "big")
        material = (
            F(b"zr/rgbr/v1") + F(session_id)
            + S(entries, self.bound_region_leaf) + F(expiry)
        )
        return hashlib.sha256(material).digest()

    # ---- binding / digest wire format ---------------------------------------

    def test_bind_once_returns_spec_digest(self):
        entries = self.entries
        guard = RegionBatchReplayGuard()
        binding = guard.bind_once(entries, b"s1")
        self.assertIsInstance(binding, ReplayBinding)
        self.assertEqual(binding.session_id, b"s1")
        self.assertIsNone(binding.expires_at)
        self.assertEqual(len(binding.digest), 32)
        self.assertEqual(binding.digest, self.expected_digest(entries, b"s1"))
        binding = guard.bind_once(entries, b"s2", expires_at=1000)
        self.assertEqual(binding.expires_at, 1000)
        self.assertEqual(
            binding.digest, self.expected_digest(entries, b"s2", 1000)
        )

    def test_tuple_and_list_inputs_frame_identically(self):
        entries = self.entries
        from_list = RegionBatchReplayGuard().bind_once(list(entries), b"s")
        from_tuple = RegionBatchReplayGuard().bind_once(tuple(entries), b"s")
        self.assertEqual(from_list.digest, from_tuple.digest)
        self.assertEqual(from_list, from_tuple)

    def test_batch_order_and_duplicates_are_preserved(self):
        entries = self.entries
        base = RegionBatchReplayGuard().bind_once(entries, b"s")

        def bind(batch):
            return RegionBatchReplayGuard().bind_once(batch, b"s").digest

        self.assertNotEqual(base.digest, bind(entries[::-1]))

class BoundOpeningReplayGuardTest(BoundOpeningReplayGuardTestBase, unittest.TestCase):
    """Single-use replay bindings for Merkle-bound hash-opening batches."""

    DOMAIN = b"zr/bobr/v1"

    def guard(self, **kwargs):
        return BoundOpeningReplayGuard(**kwargs)

    def entry(self, value):
        commitment, nonce = commit(value)
        return OpeningBatchEntry(commitment, value, nonce)

    def entries(self):
        return [self.entry(b"alpha"), self.entry(b"beta"), self.entry(b"gamma")]

    def build(self, entries):
        leaves = [bound_opening_leaf(entry) for entry in entries]
        root = merkle_root(leaves)
        proof = prove_multi_inclusion(leaves, tuple(range(len(entries))))
        return BoundOpeningBatch(tuple(entries), len(entries), proof), root

    def honest(self):
        return self.build(self.entries())

    def broken_inner_batch(self):
        # an entry whose value does not open under its commitment; the outer
        # leaves are built over the broken entry so the root check passes and
        # only verify_opening_batch rejects
        good = self.entries()[0]
        broken = OpeningBatchEntry(good.commitment, b"bogus", good.nonce)
        return self.build([broken, *self.entries()[1:]])

    def tampered_entry_batch(self, batch):
        entries = batch.entries
        tampered = OpeningBatchEntry(
            entries[0].commitment, b"other", entries[0].nonce
        )
        return BoundOpeningBatch((tampered, *entries[1:]), batch.leaf_count, batch.proof)

    def bound_leaf(self, entry):
        return bound_opening_leaf(entry)

    def delegate_name(self):
        return "verify_opening_batch_bound"

    def other_domain_binding(self, store, batch, session_id):
        other = OpeningBatchReplayGuard(store=store)
        entries = list(batch.entries)
        return other, other.bind_once(entries, session_id), entries

    @staticmethod
    def expected_digest(batch, root, session_id, expires_at=None):
        def F(item):
            return len(item).to_bytes(4, "big") + item

        def U(value):
            return value.to_bytes(8, "big")

        expiry = b"\x00" if expires_at is None else b"\x01" + expires_at.to_bytes(8, "big")
        proof = batch.proof
        material = F(b"zr/bobr/v1") + F(session_id) + F(root) + F(U(batch.leaf_count))
        material += b"".join(
            F(bound_opening_leaf(entry)) for entry in batch.entries
        )
        material += (
            F(U(proof.leaf_count))
            + F(U(len(proof.indices)))
            + b"".join(F(U(index)) for index in proof.indices)
            + F(U(len(proof.siblings)))
            + b"".join(F(sibling) for sibling in proof.siblings)
            + F(expiry)
        )
        return hashlib.sha256(material).digest()

    def test_digest_domain_is_distinct_from_other_bound_formula(self):
        import zkregion

        batch, root = self.honest()
        binding = self.guard().bind_once(batch, root, b"s")
        self.assertEqual(
            binding.digest,
            zkregion._bound_opening_replay_digest(batch, root, b"s", None),
        )
        # the identical framing under obr or another bound domain must differ
        proof = batch.proof

        def F(item):
            return len(item).to_bytes(4, "big") + item

        def U(value):
            return value.to_bytes(8, "big")

        material = F(b"zr/obr/v1") + F(b"s") + F(root) + F(U(batch.leaf_count))
        material += b"".join(
            F(bound_opening_leaf(entry)) for entry in batch.entries
        )
        material += (
            F(U(proof.leaf_count))
            + F(U(len(proof.indices)))
            + b"".join(F(U(index)) for index in proof.indices)
            + F(U(len(proof.siblings)))
            + b"".join(F(sibling) for sibling in proof.siblings)
            + F(b"\x00")
        )
        self.assertNotEqual(binding.digest, hashlib.sha256(material).digest())

    def test_nested_field_type_errors(self):
        batch, root = self.honest()
        guard = self.guard()
        entries = batch.entries
        proof = batch.proof
        cases = [
            OpeningBatchEntry(bytearray(entries[0].commitment), entries[0].value, entries[0].nonce),
            OpeningBatchEntry(entries[0].commitment, b"x", bytearray(entries[0].nonce)),
            OpeningBatchEntry(entries[0].commitment, 7, entries[0].nonce),
        ]
        for bad_entry in cases:
            with self.assertRaises(TypeError):
                guard.bind_once(
                    BoundOpeningBatch((bad_entry, *entries[1:]), batch.leaf_count, proof),
                    root, b"s",
                )


